(function(){'use strict';
const api=()=>window.CAGE_BACKEND,esc=escapeHtml,$=id=>document.getElementById(id);let data=null,search='',filter='',loading=false;
const allowed=()=>api()?.moduleLevel('training')==='edit';
function safeURL(value){try{const u=new URL(value);return u.protocol==='https:'&&u.hostname==='docs.google.com'&&u.pathname.startsWith('/forms/')&&u.pathname.endsWith('/viewform')?u.href:'';}catch{return '';}}
async function load(){if(loading||!allowed())return;loading=true;try{data=await api().stemData();render();}catch(e){const c=$('academy-content');if(c&&document.querySelector('[data-academy="tab"][data-id="stem"][aria-selected="true"]'))c.innerHTML=`<p class="academy-error">${esc(e.message)}</p><button data-stem-refresh>Retry</button>`;}finally{loading=false;}}
function render(target){const root=target||$('academy-content');if(!root||(!target&&!document.querySelector('[data-academy="tab"][data-id="stem"][aria-selected="true"]')))return;
 if(!allowed()){root.innerHTML='<div class="academy-empty">STEM applications are available to active internal members with Academy access.</div>';return;}
 if(!data){root.innerHTML='<div class="academy-empty">Loading STEM applications…</div>';load();return;}
 const rows=data.applications.filter(r=>(!filter||r.status===filter)&&`${r.respondent_email||''} ${JSON.stringify(r.answers)}`.toLowerCase().includes(search.toLowerCase())),c=data.connection,url=safeURL(c?.public_url),stats=[['Applications',data.applications.length],['New',data.applications.filter(a=>a.status==='New').length],['Accepted / enrolled',data.applications.filter(a=>['Accepted','Enrolled'].includes(a.status)).length],['Waitlisted',data.applications.filter(a=>a.status==='Waitlisted').length]];
 root.innerHTML=`<div class="academy-stats">${stats.map(([label,n])=>`<article class="academy-stat"><span>${label}</span><strong>${n}</strong></article>`).join('')}</div><article class="surface"><h3>STEM registration</h3>${c?`<p>${esc(c.form_title)} · ${c.accepting_responses?'Accepting responses':'Applications closed'}</p><p class="academy-muted">Last response received: ${c.last_received_at?esc(new Date(c.last_received_at).toLocaleString()):'No responses synced yet'}</p><div class="academy-actions"><a class="secondary-button" href="./stem.html" target="_blank" rel="noopener">Parent application page</a>${url?`<a class="secondary-button" href="${esc(url)}" target="_blank" rel="noopener">Open Google form</a>`:''}<button type="button" data-stem-refresh class="secondary-button">Refresh responses</button></div>`:'<p>The Google Form connection needs its one-time activation. Follow <strong>STEM_SETUP.md</strong> in the update package. No responses have been imported yet.</p><button type="button" data-stem-refresh class="secondary-button">Check connection</button>'}<div class="stem-status-controls"><input id="stem-search" type="search" placeholder="Search applications" aria-label="Search STEM applications" value="${esc(search)}"><select id="stem-filter" aria-label="Application status">${['','New','Under review','Accepted','Waitlisted','Declined','Enrolled'].map(s=>`<option value="${s}" ${s===filter?'selected':''}>${s||'All statuses'}</option>`).join('')}</select></div>${rows.length?`<div class="academy-table"><table><thead><tr><th>Submitted</th><th>Respondent</th><th>Status</th><th></th></tr></thead><tbody>${rows.map(r=>`<tr><td>${esc(new Date(r.submitted_at).toLocaleString())}</td><td>${esc(r.respondent_email||'Email not collected')}<br><small>${r.answers.length} answered questions</small></td><td>${esc(r.status)}</td><td><button class="secondary-button" data-stem-open="${r.id}">Review application</button></td></tr>`).join('')}</tbody></table></div>`:'<p class="academy-muted">No applications match this view.</p>'}</article>`;
}
function modal(title,html){let d=$('stem-review-dialog');if(!d){d=document.createElement('dialog');d.id='stem-review-dialog';d.className='app-dialog academy-dialog';document.body.append(d);}d.innerHTML=`<div class="dialog-heading"><h2>${esc(title)}</h2><button type="button" data-stem-close aria-label="Close">×</button></div>${html}<p class="form-error" id="stem-review-error" role="alert"></p>`;if(!d.open)d.showModal();}
const answer=v=>Array.isArray(v)?v.map(answer).join(', '):v&&typeof v==='object'?JSON.stringify(v):String(v??'');
function review(id){const r=data.applications.find(a=>a.id===id);if(!r)return;modal('STEM application',`<p>${esc(new Date(r.submitted_at).toLocaleString())} · ${esc(r.respondent_email||'Email not collected')}</p>${r.answers.map(a=>`<div class="stem-answer"><strong>${esc(a.title)}</strong><p>${esc(answer(a.answer))}</p></div>`).join('')}<form id="stem-review-form" data-record="${r.id}"><div class="form-grid"><label class="field"><span>Status</span><select name="status">${(r.learner_id?['Enrolled']:['New','Under review','Accepted','Waitlisted','Declined']).map(s=>`<option ${s===r.status?'selected':''}>${s}</option>`).join('')}</select></label><label class="field field-wide"><span>Internal review notes</span><textarea name="notes">${esc(r.notes||'')}</textarea></label></div><div class="dialog-actions"><button class="primary-button">Save review</button>${!r.learner_id?`<button type="button" class="secondary-button" data-stem-enrol="${r.id}">Enrol in STEM cohort</button>`:'<span>Linked to Academy learner record</span>'}</div></form>`);}
async function enrol(id){const training=await api().loadTraining(),cohorts=training.cohorts.filter(c=>training.courses.some(x=>x.id===c.course_id&&x.category==='STEM')&&!['Completed','Cancelled'].includes(c.status));if(!cohorts.length)throw new Error('Create a STEM cohort in the Academy first.');const r=data.applications.find(a=>a.id===id);modal('Confirm learner details',`<p>Confirm these details against the application. Consent is not assumed automatically.</p><details><summary>View submitted answers</summary>${r.answers.map(a=>`<div class="stem-answer"><strong>${esc(a.title)}</strong><p>${esc(answer(a.answer))}</p></div>`).join('')}</details><form id="stem-enrol-form" data-record="${id}"><div class="form-grid"><label class="field"><span>Cohort</span><select name="cohort" required>${cohorts.map(c=>`<option value="${c.id}">${esc(c.name)}</option>`).join('')}</select></label>${[['full_name','Learner full name','text',true],['date_of_birth','Date of birth','date',false],['guardian_name','Parent / guardian name','text',true],['guardian_phone','Parent / guardian phone','text',true],['email','Parent / guardian email','email',false]].map(([name,label,type,required])=>`<label class="field"><span>${label}</span><input name="${name}" type="${type}" ${required?'required':''} value="${name==='email'?esc(r.respondent_email||''):''}"></label>`).join('')}<label class="check-field field-wide"><input name="guardian_consent" type="checkbox"><span>I have checked the parent / guardian consent</span></label></div><div class="dialog-actions"><button class="primary-button">Create learner record</button></div></form>`);}
document.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b)return;try{if(b.hasAttribute('data-stem-refresh'))await load();if(b.dataset.stemOpen)review(b.dataset.stemOpen);if(b.dataset.stemEnrol)await enrol(b.dataset.stemEnrol);if(b.hasAttribute('data-stem-close'))$('stem-review-dialog').close();}catch(err){if($('stem-review-error'))$('stem-review-error').textContent=err.message;else showToast(err.message);}});
document.addEventListener('submit',async e=>{const f=e.target;if(!['stem-review-form','stem-enrol-form'].includes(f.id))return;e.preventDefault();if(f.dataset.submitting)return;f.dataset.submitting='true';const b=e.submitter;b.disabled=true;try{const v=Object.fromEntries(new FormData(f));if(f.id==='stem-review-form')await api().reviewStem(f.dataset.record,v);else{v.guardian_consent=!!v.guardian_consent;await api().enrolStem(f.dataset.record,v.cohort,v);await window.CAGE_ACADEMY?.load();}$('stem-review-dialog').close();await load();showToast('STEM application saved.');}catch(err){$('stem-review-error').textContent=err.message;}finally{delete f.dataset.submitting;b.disabled=false;}});
document.addEventListener('input',e=>{if(e.target.id==='stem-search'){search=e.target.value;const pos=e.target.selectionStart;render();$('stem-search').focus();$('stem-search').setSelectionRange(pos,pos);}});document.addEventListener('change',e=>{if(e.target.id==='stem-filter'){filter=e.target.value;render();}});
window.addEventListener('cage:session-ready',()=>{data=null;search='';filter='';});
window.CAGE_STEM={render,async restore(saved){await load();const f=saved.forms.find(f=>['stem-review-form','stem-enrol-form'].includes(f.id));if(f){if(f.id==='stem-enrol-form')await enrol(f.data.record);else review(f.data.record);}}};
})();
